/** Serialize only runtime catalogue fields as data, never as source fragments. */
export function serializeAuraTrackCatalog(tracks) {
  const entries = tracks.map((track) => ({
    id: track.id,
    title: track.title,
    url: track.url,
    bpm: track.bpm,
    beatOffsetMs: track.beatOffsetMs,
    ...(track.durationMs ? { durationMs: track.durationMs } : {}),
    ...(track.stageId ? { stageId: track.stageId } : {}),
  }));
  return [
    '// Generated by scripts/measure-aura-tracks.mjs. Do not edit by hand:',
    '// put manual corrections in AURA_TRACK_OVERRIDES inside AuraTracks.ts.',
    `export const AURA_TRACKS_GENERATED = ${JSON.stringify(entries, null, 2)} as const;`,
    '',
  ].join('\n');
}
